function findShortestSubArray(nums) {
  const count = new Map();
  const first = new Map();
  let degree = 0;
  let shortest = 0;

  for (let i = 0; i < nums.length; i++) {
    const value = nums[i];
    if (!first.has(value)) {
      first.set(value, i);
    }
    const seen = (count.get(value) ?? 0) + 1;
    count.set(value, seen);
    const length = i - first.get(value) + 1;
    if (seen > degree) {
      degree = seen;
      shortest = length;
    } else if (seen === degree) {
      shortest = Math.min(shortest, length);
    }
  }
  return shortest;
}

