function findShortestSubArray(nums) {
  // Degree of the whole array by plain counting.
  const total = {};
  let target = 0;
  for (const v of nums) {
    total[v] = (total[v] || 0) + 1;
    target = Math.max(target, total[v]);
  }
  // Try every start; grow the window until its own degree reaches the target.
  let best = nums.length;
  for (let start = 0; start < nums.length; start++) {
    const window = {};
    let top = 0;
    for (let end = start; end < nums.length && end - start + 1 <= best; end++) {
      window[nums[end]] = (window[nums[end]] || 0) + 1;
      top = Math.max(top, window[nums[end]]);
      if (top === target) {
        best = Math.min(best, end - start + 1);
        break;
      }
    }
  }
  return best;
}

