function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const span = size === 'large'
    ? [3, 50, 700, 50000][Math.floor(rand() * 4)]
    : 1 + Math.floor(rand() * 5);
  const edge = rand() < 0.3;
  const nums = [];
  for (let i = 0; i < n; i++) {
    const v = Math.floor(rand() * span);
    nums.push(edge && rand() < 0.5 ? 49999 - v : v);
  }
  return [nums];
}
